        # Normalize weights in-place
        self.maps = [IFSMap(m.a, m.b, m.c, m.d, m.e, m.f, m.weight / total) for m in self.maps]

# ---------------------------------------------------------------------------
# Built-in systems
# ---------------------------------------------------------------------------

def builtin_fern() -> IFSSystem:
    """Classic Barnsley fern (4 maps)."""
    maps = [
        IFSMap(0.0, 0.0, 0.0, 0.16, 0.0, 0.0, 0.01),
        IFSMap(0.85, 0.04, -0.04, 0.85, 0.0, 1.6, 0.85),
        IFSMap(0.2, -0.26, 0.23, 0.22, 0.0, 1.6, 0.07),
        IFSMap(-0.15, 0.28, 0.26, 0.24, 0.0, 0.44, 0.07),
    ]
    return IFSSystem(name="fern", maps=maps)

def builtin_sierpinski() -> IFSSystem:
    """Sierpinski triangle (3 maps)."""
    w = 1.0 / 3.0
    maps = [
        IFSMap(0.5, 0.0, 0.0, 0.5, 0.0, 0.0, w),
        IFSMap(0.5, 0.0, 0.0, 0.5, 0.5, 0.0, w),
        IFSMap(0.25, 0.433, -0.433, 0.25, 0.75, 0.0, w),
    ]
    return IFSSystem(name="sierpinski", maps=maps)

# ---------------------------------------------------------------------------
# File parser
# ---------------------------------------------------------------------------

def load_ifs(path: Union[str, Path]) -> IFSSystem:
    """Parse an IFS file and return an IFSSystem.

    Format per data line (7 space-separated floats):
        a  b  c  d  e  f  weight

    Blank lines and lines starting with '#' are skipped.
    The system name is taken from the file stem.
    """
    path = Path(path)
    maps: list[IFSMap] = []
    line_num = 0

    for raw_line in path.read_text().splitlines():
        line_num += 1
        stripped = raw_line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        parts = stripped.split()
        if len(parts) != 7:
            raise ValueError(f"line {line_num}: expected 7 fields, got {len(parts)}")
        try:
            vals = [float(p) for p in parts]
        except ValueError as exc:
            # Identify the offending token
            for i, p in enumerate(parts):
                try:
                    float(p)
                except ValueError:
                    raise ValueError(f"line {line_num}: non-numeric value '{p}'") from None
            raise  # unreachable but satisfies type checker
        a, b, c, d, e, f, weight = vals
        if weight < 0.0:
            raise ValueError(f"negative weight on line {line_num}")
        maps.append(IFSMap(a, b, c, d, e, f, weight))

    return IFSSystem(name=path.stem, maps=maps)
